mapper.select:
select m.id, m.user_id as userId, u.account_name as accountName, u.status as userStatus, m.plan_id as planId, m.tier, m.status, m.started_at as startedAt, m.expires_at as expiresAt, m.created_at as createdAt, m.updated_at as updatedAt from cm_user_memberships m join cm_users u on u.id = m.user_id
( m.id like concat('%', #{keyword}, '%') or m.user_id like concat('%', #{keyword}, '%') or u.account_name like concat('%', #{keyword}, '%') )
and m.status = #{status}
and m.tier = #{tier}
order by m.created_at desc, m.id desc
